import{c as s,Q as a,j as t,m as o}from"./chunks/framework.DjobWxAB.js";const b=JSON.parse('{"title":"rbq_example_level_0","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/software/examples/rbq_example_Level0.md","filePath":"ko/software/examples/rbq_example_Level0.md","lastUpdated":1779182288000}'),i={name:"ko/software/examples/rbq_example_Level0.md"};function l(r,e,d,n,p,c){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="rbq-example-level-0" tabindex="-1">rbq_example_level_0 <a class="header-anchor" href="#rbq-example-level-0" aria-label="Permalink to &quot;rbq_example_level_0&quot;">​</a></h1><p>저장소의 <strong><code>rbq_examples</code></strong> 아래에 있는 C++ 예제로, RBQ 스택과 <strong>저수준(LV0 스타일)</strong> 으로 통신하는 방법을 보여 줍니다. IMU·조이스틱·다리 관절 토픽을 구독하고, 다리 모션 레퍼런스와 관절 소유권 명령을 발행하며, 명령줄로 넘긴 <strong>학습 보행 정책(ONNX)</strong> 을 선택적으로 실행합니다.</p><p>이 예제를 빌드·실행하기 전에 <a href="/RBQ/ko/software/rbq-sdk.html"><strong>RBQ SDK</strong></a>를 빌드·설치해 두어야 합니다. SDK가 없거나 CMake가 찾지 못하면 <code>rbq_examples</code> 빌드가 실패합니다.</p><h2 id="동작-요약" tabindex="-1">동작 요약 <a class="header-anchor" href="#동작-요약" aria-label="Permalink to &quot;동작 요약&quot;">​</a></h2><ul><li><strong>제어 루프 스레드</strong>가 DDS로 실행 중인 RBQ 모션 스택(실기 또는 <code>scripts/sim.bash</code>로 띄운 <strong>시뮬</strong>)과 통신합니다.</li><li><strong>Idle</strong>: 스택의 최종 다리 레퍼런스를 추종하며 호환되는 <code>MotionRef</code>를 발행합니다.</li><li><strong>Motion</strong>(앉기/서기 등 키): <code>JointControl</code>로 포즈를 보간한 뒤 레퍼런스·소유권을 발행합니다.</li><li><strong>Walk / Control</strong>: <code>-p</code>로 정책을 읽어 IMU·관절·명령 관측으로 ONNX 추론 후, 정책 게인으로 <code>MotionRef</code>를 발행합니다.</li></ul><h2 id="빌드-rbq-examples" tabindex="-1">빌드 (<code>rbq_examples/</code>) <a class="header-anchor" href="#빌드-rbq-examples" aria-label="Permalink to &quot;빌드 (`rbq_examples/`)&quot;">​</a></h2><ol><li><p>저장소 스크립트에 따라 의존성 설치(ONNX 등은 <code>rbq_examples/scripts/install/apt.bash</code> 등 참고).</p></li><li><p><strong><code>rbq_sdk</code></strong> 가 설치되어 있고, 기본 경로가 아니면 <code>CMAKE_PREFIX_PATH</code>에 설치 접두어를 넣습니다.</p></li><li><p><strong><code>rbq_examples</code></strong> 디렉터리에서:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/setup.bash</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 시스템 의존성 등 (setup.bash는 sudo로 실행하지 마세요)</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build.bash</span></span></code></pre></div><p>빌드 스크립트 설정에 따라 결과물은 프로젝트 <strong><code>bin/</code></strong> 등에 설치됩니다.</p></li></ol><h2 id="정책-번들-p" tabindex="-1">정책 번들 (<code>-p</code>) <a class="header-anchor" href="#정책-번들-p" aria-label="Permalink to &quot;정책 번들 (`-p`)&quot;">​</a></h2><p>걷기 모드에는 <strong><code>info.json</code></strong> 및 <code>rbq_sdk::Policy</code> / <code>PolicyParams</code>가 기대하는 ONNX가 들어 있는 <strong>정책 디렉터리</strong>가 필요합니다.</p><p>예:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_example_level_0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./../resources/policy/rbq10_trot/</span></span></code></pre></div><p>애플리케이션은 <strong><code>-p</code>를 필수</strong>로 요구합니다.</p><h2 id="시뮬레이션에서-실행" tabindex="-1">시뮬레이션에서 실행 <a class="header-anchor" href="#시뮬레이션에서-실행" aria-label="Permalink to &quot;시뮬레이션에서 실행&quot;">​</a></h2><ol><li><p><strong>RBQ 저장소 루트</strong>에서 <a href="/RBQ/ko/software/developers-guide.html">개발자 가이드</a>에 따라 스택을 띄웁니다(시뮬용 Motion + MuJoCo + GUI):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/sim.bash</span></span></code></pre></div></li><li><p>GUI에서 매뉴얼에 나온 대로 <strong>시뮬레이터 연결</strong> 후 <strong>제어 시작</strong> 절차를 진행합니다. 스택이 제어 가능한 상태가 되려면 <strong>Auto Start(오토 스타트)</strong> 등으로 모션·제어 경로가 올라와 있어야 하며, 단계를 건너뛰면 예제가 토픽을 받지 못할 수 있습니다.</p></li><li><p>빌드 후 **<code>rbq_examples</code>**에서 예제 실행:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_example_level_0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./../resources/policy/rbq10_trot/</span></span></code></pre></div></li></ol><p><strong>실시간</strong> 제어 스레드 경로를 쓰려면 <strong><code>sudo</code></strong> 로 실행할 수 있습니다. root가 아니면 일반 스레드로 동작합니다.</p><h2 id="키보드·조작" tabindex="-1">키보드·조작 <a class="header-anchor" href="#키보드·조작" aria-label="Permalink to &quot;키보드·조작&quot;">​</a></h2><p>시작 시 도움말이 출력됩니다. 대표적으로(정확한 목록은 소스 <code>printHelp()</code> 참고):</p><table tabindex="0"><thead><tr><th>키</th><th>동작</th></tr></thead><tbody><tr><td><code>q</code></td><td>종료</td></tr><tr><td><code>z</code></td><td>앉기/그라운드 쪽 모션 시퀀스</td></tr><tr><td><code>x</code></td><td>서기/레디 쪽 모션 시퀀스</td></tr><tr><td><code>c</code></td><td><strong>제어/걷기</strong> 모드 (<code>-p</code> 정책 사용)</td></tr></tbody></table><p>제어 모드에서는 <strong>게임패드</strong> 축으로 속도형 명령을 넣습니다(화면 도움말 참고).</p><h2 id="dds-토픽" tabindex="-1">DDS 토픽 <a class="header-anchor" href="#dds-토픽" aria-label="Permalink to &quot;DDS 토픽&quot;">​</a></h2><p>예제는 예를 들어 다음과 같은 문자열 토픽을 사용합니다:</p><ul><li>구독: <code>rt/rbq/cmd/joy/final</code>, <code>rt/rbq/info/imu</code>, <code>rt/rbq/info/leg_joint</code>, <code>rt/rbq/ref/leg_joint/final</code> 등</li><li>발행: <code>rt/rbq/ref/leg_joint/owner_20</code>, <code>rt/rbq/cmd/motion/joint_owner/20</code> 등</li></ul><p>정확한 이름·의미는 <strong>실행 중인 로봇 소프트웨어 버전</strong>과 일치해야 합니다.</p><h2 id="문제-해결" tabindex="-1">문제 해결 <a class="header-anchor" href="#문제-해결" aria-label="Permalink to &quot;문제 해결&quot;">​</a></h2><ul><li><strong>동작 없음 / 토픽 없음</strong>: <code>sim.bash</code>(또는 실기 스택)가 떠 있는지, DDS가 올바른 네트워크 인터페이스를 쓰는지 확인합니다.</li><li><strong>정책 오류</strong>: <code>-p</code> 경로가 유효한지, ONNX가 설치된 <strong>onnxruntime</strong>과 맞는지, <code>info.json</code>의 타입(<code>rbq10</code>, <code>rbq10_trot</code> 등)이 맞는지 확인합니다.</li><li><strong>apt 인증 오류</strong> 등: 호스트의 GPG/소스 설정 문제로, 예제 자체와는 별도로 해결합니다.</li></ul><h2 id="더-보기" tabindex="-1">더 보기 <a class="header-anchor" href="#더-보기" aria-label="Permalink to &quot;더 보기&quot;">​</a></h2><ul><li><a href="/RBQ/ko/software/rbq-sdk.html">RBQ SDK</a></li><li><a href="/RBQ/ko/manual/Guides/developer-level-0.html">Level 0 개발자 가이드</a></li><li><a href="/RBQ/ko/software/Concept.html">Concept — Low level / LV0</a></li></ul>',27)])])}const g=s(i,[["render",l]]);export{b as __pageData,g as default};
